/**
Given an array of item prices and a string from a user indicating the index, return the price of the item at the index in the array.

@param prices: the array of item prices
@param size: the size of the array
@param index_str: the string indicating the index
@return the price of the item at the index in the array. Returns a specific error code if input is invalid or index is out of bounds.
*/
int get_price_at_index(int* prices, int size, char* index_str) {
    char* endptr;
    long index_long;
    int index;

    // Check if the prices array is a null pointer
    if (prices == NULL) {
        // Invalid input: null prices array.
        // Returning a value that cannot be a valid price.
        // Assuming prices are non-negative, INT_MIN can serve as an error indicator.
        return INT_MIN;
    }

    errno = 0; // Clear errno before calling strtol

    index_long = strtol(index_str, &endptr, 10);

    // Check for conversion errors:
    // 1. errno != 0: indicates a conversion error (e.g., overflow, invalid characters).
    // 2. *endptr != '\0': indicates that not all characters in index_str were converted (e.g., "123a").
    // 3. endptr == index_str: indicates that no characters were converted (e.g., empty string or only non-numeric characters).
    if (errno != 0 || *endptr != '\0' || endptr == index_str) {
        // Invalid input string.
        return INT_MIN;
    }

    // Check for overflow/underflow of the converted long value to ensure it fits within int.
    if (index_long > INT_MAX || index_long < INT_MIN) {
        // Index out of range for int type.
        return INT_MIN;
    }

    index = (int)index_long;

    // Check if the index is within the bounds of the array
    if (index >= 0 && index < size) {
        return prices[index];
    } else {
        // Index out of bounds for the array.
        return INT_MIN;
    }
}
